            log::warn!(
                "ticket {} {}/{}: workflow query failed: {reason}; asking again",
                t.id,
                a.stage,
                a.context
            );
            return self.save_ticket(t, now_ms);
        }
        other => bail!("workflow query answered {other:?}"),
    };
    let idx = t
        .attempts
        .iter()
        .position(|x| x.stage == a.stage && x.n == a.n)
        .expect("the attempt exists");
